/**
 * The hooks' scratch space: `<config>/.cache`, shared by the hooks (per-session counters and
 * snapshots, the guards' error log). Everything here is best-effort: a cache that cannot
 * be read or written costs a recomputation, never a failure.
 *
 * Generated by Claude Code at the user's request.
 */

'use strict';

const fs = require('fs');
const os = require('os');
const path = require('path');

/** CLAUDE_CONFIG_DIR, Claude Code's own variable, so a relocated configuration keeps its cache with it. */
const CONFIG_DIR = process.env.CLAUDE_CONFIG_DIR || path.join(os.homedir(), '.claude');
const CACHE_DIR = path.join(CONFIG_DIR, '.cache');
const PRUNE_AFTER_MS = 3 * 24 * 60 * 60 * 1000;

/** The parsed JSON file, or null when it is missing or unreadable. */
function readJson(file) {
  try {
    return JSON.parse(fs.readFileSync(file, 'utf8'));
  } catch {
    return null;
  }
}

/** Remove the cache files matching `pattern` that were last written more than `maxAgeMs` before `now`. */
function prune(pattern, now = Date.now(), maxAgeMs = PRUNE_AFTER_MS) {
  try {
    for (const name of fs.readdirSync(CACHE_DIR)) {
      if (!pattern.test(name)) continue;
      const file = path.join(CACHE_DIR, name);
      if (now - fs.statSync(file).mtimeMs > maxAgeMs) fs.rmSync(file, { force: true });
    }
  } catch {
    /* best-effort */
  }
}

const ERROR_LOG = path.join(CACHE_DIR, 'hook-errors.log');
const ERROR_LOG_MAX_BYTES = 16 * 1024;

/**
 * One line per error a hook swallowed, in `<cache>/hook-errors.log`, so "the guard said nothing" can
 * be told apart from "the guard crashed". Capped: past the limit the oldest half is dropped.
 */
function logError(hook, error) {
  try {
    const message = String(error?.stack ?? error?.message ?? error).split('\n').slice(0, 2).join(' | ').slice(0, 300);
    fs.mkdirSync(CACHE_DIR, { recursive: true });
    if (fs.existsSync(ERROR_LOG) && fs.statSync(ERROR_LOG).size > ERROR_LOG_MAX_BYTES) {
      const tail = fs.readFileSync(ERROR_LOG, 'utf8').slice(-ERROR_LOG_MAX_BYTES / 2);
      fs.writeFileSync(ERROR_LOG, tail.slice(tail.indexOf('\n') + 1));
    }
    fs.appendFileSync(ERROR_LOG, `${new Date().toISOString()} ${hook}: ${message}\n`);
  } catch {
    /* the log must never be what fails */
  }
}

module.exports = { CONFIG_DIR, CACHE_DIR, readJson, prune, logError, ERROR_LOG };
